+// Modal Dialog Component
+class DeleteConfirmationModal {
+  constructor() {
+    this.modal = document.getElementById('deleteModal');
+    this.overlay = this.modal.querySelector('.modal-overlay');
+    this.closeBtn = this.modal.querySelector('.modal-close');
+    this.cancelBtn = document.getElementById('cancelBtn');
+    this.confirmDeleteBtn = document.getElementById('confirmDeleteBtn');
+    this.triggerButtons = document.querySelectorAll('.trigger');
+    
+    this.currentImageId = null;
+    this.init();
+  }
+
+  init() {
+    // Open modal when trigger button is clicked
+    this.triggerButtons.forEach(btn => {
+      btn.addEventListener('click', (e) => this.open(e));
+    });
+
+    // Close modal handlers
+    this.closeBtn.addEventListener('click', () => this.close());
+    this.cancelBtn.addEventListener('click', () => this.close());
+    this.overlay.addEventListener('click', () => this.close());
+
+    // Confirm delete handler
+    this.confirmDeleteBtn.addEventListener('click', () => this.handleDelete());
+
+    // Close modal on Escape key
+    document.addEventListener('keydown', (e) => {
+      if (e.key === 'Escape' && this.modal.classList.contains('open')) {
+        this.close();
+      }
+    });
+  }
+
+  open(event) {
+    const button = event.target;
+    this.currentImageId = button.dataset.imageId;
+    this.modal.classList.add('open');
+    this.modal.setAttribute('aria-hidden', 'false');
+    document.body.style.overflow = 'hidden';
+  }
+
+  close() {
+    this.modal.classList.remove('open');
+    this.modal.setAttribute('aria-hidden', 'true');
+    document.body.style.overflow = '';
+    this.currentImageId = null;
+  }
+
+  handleDelete() {
+    const imageId = this.currentImageId;
+    const imageCard = document.querySelector(`[data-image-id="${imageId}"]`).closest('.image-card');
+    
+    // Fade out animation
+    imageCard.style.opacity = '0';
+    imageCard.style.transform = 'scale(0.95)';
+    
+    setTimeout(() => {
+      imageCard.remove();
+      this.close();
+      
+      // Show feedback
+      this.showDeleteNotification();
+    }, 300);
+  }
+
+  showDeleteNotification() {
+    const notification = document.createElement('div');
+    notification.style.cssText = `
+      position: fixed;
+      bottom: 20px;
+      right: 20px;
+      background-color: #10b981;
+      color: white;
+      padding: 16px 24px;
